package main

import (
	"fmt"
	"regexp"
)

func main() {
	cronRegexString := `(@(annually|yearly|monthly|weekly|daily|hourly|reboot))|(@every (\d+(ns|us|µs|ms|s|m|h))+)|((((\d+,)+\d+|((\*|\d+)(\/|-)\d+)|\d+|\*) ?){5,7})`

	regex := regexp.MustCompile(cronRegexString)

	// Valid cron expressions
	validTests := []string{
		"0 0 12 * * ?",
		"0 15 10 ? * *",
		"0 15 10 * * ?",
		"0 15 10 * * ? 2005",
		"0 15 10 ? * 6L",
		"0 15 10 ? * 6L 2002-2005",
		"*/20 * * * *",
		"0 15 10 ? * MON-FRI",
		"0 15 10 ? * 6#3",
		"0 */15 * * *",
	}

	// Invalid but potentially matching substrings
	invalidTests := []string{
		"wrong",
		"0 15 10 * * ? abc",
		"foo 0 15 10 * * ? bar", 
		"some text 0 15 10 * * ? more text",
	}

	fmt.Println("Valid cron expressions:")
	for _, test := range validTests {
		if regex.MatchString(test) {
			fmt.Printf("✓ %s\n", test)
		} else {
			fmt.Printf("✗ %s\n", test)
		}
	}

	fmt.Println("\nInvalid cron expressions (but still matching due to lack of anchoring):")
	for _, test := range invalidTests {
		if regex.MatchString(test) {
			fmt.Printf("✓ %s (should be FALSE but matching)\n", test)
		} else {
			fmt.Printf("✗ %s\n", test)
		}
	}
}

package main

import (
	"fmt"
