package main

import (
	"fmt"
	"regexp"
)

func main() {
	// Original (unanchored) pattern - how it used to work
	origPattern := `(@(annually|yearly|monthly|weekly|daily|hourly|reboot))|(@every (\d+(ns|us|µs|ms|s|m|h))+)|((((\d+,)+\d+|((\*|\d+)(\/|-)\d+)|\d+|\*) ?){5,7})`

	// Anchored pattern - with our fix
	fixedPattern := `^(@(annually|yearly|monthly|weekly|daily|hourly|reboot))|(@every (\d+(ns|us|µs|ms|s|m|h))+)|((((\d+,)+\d+|((\*|\d+)(\/|-)\d+)|\d+|\*) ?){5,7})$`

	origRegex := regexp.MustCompile(origPattern)
	fixedRegex := regexp.MustCompile(fixedPattern)

	// Test cases from the actual test suite
	testCases := []string{
		"0 0 12 * * ?",           // Should be valid
		"0 15 10 ? * *",          // Should be valid  
		"0 15 10 * * ?",          // Should be valid
		"0 15 10 * * ? 2005",     // Should be valid
		"0 15 10 ? * 6L",         // Should be valid (6L = Friday last week)
		"0 15 10 ? * 6L 2002-2005", // Should be valid  
		"*/20 * * * *",           // Should be valid
		"0 15 10 ? * MON-FRI",    // Should be valid
		"0 15 10 ? * 6#3",        // Should be valid (6#3 = third Friday)
		"0 */15 * * *",           // Should be valid
		"wrong",                  // Should be invalid
		"0 15 10 * * ? abc",      // Should be invalid (contains embedded cron)
		"foo 0 15 10 * * ? bar",  // Should be invalid (contains embedded cron)
	}

	fmt.Println("=== Original Pattern Behavior ===")
	for _, test := range testCases {
		match := origRegex.MatchString(test)
		fmt.Printf("%-30s -> %v\n", test, match)
	}

	fmt.Println("\n=== Fixed Pattern Behavior ===")
	for _, test := range testCases {
		match := fixedRegex.MatchString(test)
		fmt.Printf("%-30s -> %v\n", test, match)
	}
}
